contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint val, uint newVal) public {
        bool success1;
        c.SetMinSum(val); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            success1 = false;
        } else {
            success1 = true;
        }
        require(success1);

        bool success2;
        c.SetMinSum(newVal); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            success2 = false;
        } else {
            success2 = true;
        }

        assert(!success1 || !success2 || c.MinSum() == newVal);
    }

    receive() external payable {}
}

