pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 val, uint256 newVal) internal {
        bool success1;
        try c.SetMinSum(val) {
            success1 = true;
        } catch {
            success1 = false;
        }
        vm.assume(success1);
        bool success2;
        try c.SetMinSum(newVal) {
            success2 = true;
        } catch {
            success2 = false;
        }
        assertTrue(!success1 || !success2 || c.MinSum() == newVal);
    }

    function testFuzz_run(uint256 val, uint256 newVal) public {
        _run(val, newVal);
    }

    receive() external payable {}
}
